import { useEffect, useState } from "react";
import { getSnippet } from "../api/client";
import { serializeSup } from "../lib/evolve";
import { useAppStore } from "../state/store";

/**
 * The Python that reproduces the view on screen, from the atomsim package.
 *
 * Generated by the server (snippets.py), whose tests execute every variant, so
 * what is offered here is code that has been run, not code that looks right.
 * Fetched only once the reader opens it.
 */
export function ReproduceInPython() {
  const s = useAppStore();
  const [open, setOpen] = useState(false);
  const [code, setCode] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const params = new URLSearchParams({
    view: s.view,
    n: String(s.n),
    l: String(s.l),
    m: String(s.m),
    system: s.system,
    basis: s.basis,
    model: s.model,
    plane: s.planeQuantity,
    count: String(s.count),
  });
  if (s.hybrid) params.set("hybrid", s.hybrid);
  for (const sup of serializeSup(s.superposition)) params.append("sup", sup);
  const query = params.toString();

  useEffect(() => {
    setCode(null);
    setCopied(false);
    if (!open) return;
    let live = true;
    getSnippet(query).then(
      (c) => live && setCode(c),
      (e) => live && setCode(`# could not build a snippet: ${e instanceof Error ? e.message : e}`),
    );
    return () => {
      live = false;
    };
  }, [open, query]);

  return (
    <details
      className="reproduce"
      onToggle={(e) => setOpen((e.target as HTMLDetailsElement).open)}
    >
      <summary>Reproduce in Python</summary>
      <p className="caption">
        The same engine call this view made, ready to paste after{" "}
        <code>pip install</code>ing this repository. Every result prints with its fidelity
        tier.
      </p>
      {code === null ? (
        <p className="hint">building…</p>
      ) : (
        <>
          <pre className="snippet">
            <code>{code}</code>
          </pre>
          <button
            type="button"
            className="ghost"
            onClick={() =>
              void navigator.clipboard?.writeText(code).then(
                () => setCopied(true),
                () => {},
              )
            }
          >
            {copied ? "Copied" : "Copy"}
          </button>
        </>
      )}
    </details>
  );
}
